import {extractionTasks,electronTasks,validElectronAccount} from './redox-models.js?v=20261023-physicscomplete01';
import {showRedox} from './redox-scenes.js?v=20261023-physicscomplete01';
const select=(id,label,options,value='')=>`<label class="field-label" for="${id}">${label}</label><select class="lab-select" id="${id}"><option value="">Choose…</option>${options.map(([v,t])=>`<option value="${v}" ${value===v?'selected':''}>${t}</option>`).join('')}</select>`;
const field=(id,label)=>`<label class="field-label" for="${id}">${label}</label><input class="lab-input" id="${id}" type="text" autocomplete="off" spellcheck="false">`;
export function mountRedoxWidget(l,p,root,{save,done,feedback}){const w=p.widget;w.task??=0;w.answers??={};w.passed??=[];const i=w.task,a=w.answers[i]??={},electron=l.widget==='redox-electrons',t=(electron?electronTasks:extractionTasks)[i],kind=electron?'electrons':'extraction',$=s=>root.querySelector(s),fields=electron?['oxidation','reduction','ionic']:['method','reason'];root.innerHTML=`<p><b>Case ${i+1} / 3</b></p>`+(electron?`<p>${t} displaces copper from Cu²⁺ solution. Write both half-equations and the net ionic equation. ${t} forms 2+ ions; Cu²⁺ becomes Cu.</p><p class="micro-note">Type -> for an arrow, 2+ for charge and 2e- for two electrons. Unicode charges/arrows and either term order are also accepted. Omit spectator ions.</p>`+field('oxidation','Oxidation half-equation')+field('reduction','Reduction half-equation')+field('ionic','Net ionic equation'):`<p>${t.evidence}</p>`+select('method','Extraction route',[['carbon','Carbon reduction of oxide'],['other','Another chemical route; carbon is unsuitable'],['physical','Physical separation of native metal']],a.method)+select('reason','Reason',[['native','Already present as metal'],['above','Metal is more reactive than carbon'],['below','Metal is less reactive than carbon']],a.reason))+`<button class="secondary" id="checkRedox">Check the account</button><button class="secondary" id="nextRedox">Next case →</button><p id="redoxProgress">${w.passed.length} / 3 cases correct</p>`;
 fields.forEach(k=>{if(electron)$('#'+k).value=a[k]||'';$('#'+k)[electron?'oninput':'onchange']=e=>{a[k]=e.target.value;save();};});showRedox(kind,t,w.passed.includes(i));$('#checkRedox').onclick=()=>{const ok=electron?validElectronAccount(t,a.oxidation||'',a.reduction||'',a.ionic||''):a.method===t.method&&a.reason===t.reason;if(!ok){feedback(electron?'The metal loses 2 electrons; Cu²⁺ gains 2. Keep electrons on the correct side of each half-equation, use 2+ metal ions, cancel electrons in the net equation and omit spectators. Check atoms and charge.':'Check the starting material first. Native metal needs separation; an oxide below carbon can be reduced with carbon; an oxide above carbon needs another chemical route.',true);return;}if(!w.passed.includes(i))w.passed.push(i);save();showRedox(kind,t,true);$('#redoxProgress').textContent=w.passed.length+' / 3 cases correct';feedback(electron?'Correct. Both half-equations and the net ionic equation conserve atoms and charge.':'Correct. The extraction route follows the supplied material and reactivity evidence.');if(w.passed.length===3){p.widgetDone=true;save();done();}};$('#nextRedox').onclick=()=>{w.task=(i+1)%3;save();mountRedoxWidget(l,p,root,{save,done,feedback});};}
